\begin{array} {l} {{{P ( X ( t )=j \ \big| \ N ( t )=n )=P \big| \sum_{t=1}^{n} Y_{t}=0 \Big| n ( t )=j }} e^{t}} \\ {{{E ( X ( t ) )= N ( t ) E ( Y )+\gamma \lambda t-N ( t )}}} \\ \end{array}
$$
